#' @title 
#' Convert emission estimates from list to data.table format
#' 
#' @description 
#' Read emission estimates generated by the \code{\link{emission_model}} or from
#' emission factor functions (e.g. \code{\link{ef_brazil_cetesb}}) and convert 
#' them into a `data.table` format.
#' 
#' @param emi_list list. A list of emission estimates
#' @param emi_vars character. Name of the single element of `emi_list` that 
#'        holds emissions or emission factors. Default is 'emi'.
#' @param veh_vars character. data.frame names of 'emi_list' object attributed 
#'        to vehicle characteristics. Default is 'veh_type'.
#' @param pol_vars character. data.frame names of 'emi_list' object attributed 
#'        to pollutants. Default is 'pollutant'.
#' @param segment_vars character. data.frame names of 'emi_list' object 
#'        attributed to the road segments. Default is NULL.
#' @param process_vars character. data.frame names of 'emi_list' object 
#'        attributed to the emission processes. Default is 'process'.
#'        
#' @return data.table.
#' 
#' @family emission analysis

#' @examples
#' \donttest{
#'  if (requireNamespace("gtfstools", quietly=TRUE)) {
#' 
#' # read GTFS
#' gtfs_file <- system.file("extdata/bra_cur_gtfs.zip", package = "gtfs2emis")
#' gtfs <- gtfstools::read_gtfs(gtfs_file) 
#' 
#' # keep a single trip_id to speed up this example
#' gtfs_small <- gtfstools::filter_by_trip_id(gtfs, trip_id ="4451136")
#'   
#' # run transport model
#' tp_model <- transport_model(gtfs_data = gtfs_small,
#'                             min_speed = 2,
#'                             max_speed = 80,
#'                             new_speed = 20,
#'                             spatial_resolution = 100)
#' 
#' # Example using Brazilian emission model and fleet
#' fleet_data_ef_cetesb <- data.frame(veh_type = "BUS_URBAN_D",
#'                                    model_year = 2010:2019,
#'                                    fuel = "D",
#'                                    fleet_composition = rep(0.1,10)
#'                                    )
#'                                    
#' emi_list <- emission_model(
#'                 tp_model = tp_model,
#'                 ef_model = "ef_brazil_cetesb",
#'                 fleet_data = fleet_data_ef_cetesb,
#'                 pollutant = c("CO","PM10","CO2","CH4","NOx")
#'                 )
#' 
#' # convert emission list to data.table
#' dt <- emis_to_dt(emi_list)
#' }
#' }
#' @export
emis_to_dt <- function(emi_list, emi_vars = "emi", veh_vars = "veh_type"
                       , pol_vars = "pollutant", process_vars = "process", segment_vars = NULL){
  
  
  # emi_list = cur_local_ef
  # emi_vars = "EF"
  # veh_vars = "veh_type"
  # pol_vars = "pollutant"
  # process_vars = "process"
  # segment_vars = NULL
  # checkings -----
  assert_list(emi_list, null.ok = FALSE)
  # emi_vars
  assert_string(emi_vars)
  assert_choice(emi_vars,names(emi_list),null.ok = FALSE)
  # veh_vars
  assert_vector(veh_vars,any.missing = FALSE,min.len = 1,null.ok = FALSE)
  assert_character(veh_vars,any.missing = FALSE,min.len = 1)
  for(i in veh_vars) assert_choice(i,names(emi_list),null.ok = FALSE, .var.name = "veh_vars")
  # pol_vars
  assert_vector(pol_vars,any.missing = FALSE,min.len = 1,null.ok = FALSE)
  assert_character(pol_vars,any.missing = FALSE,min.len = 1)
  for(i in pol_vars) assert_choice(i,names(emi_list),null.ok = FALSE, .var.name = "pol_vars")
  # process
  assert_vector(process_vars,any.missing = FALSE,min.len = 1,null.ok = FALSE)
  assert_character(process_vars,any.missing = FALSE,min.len = 1)
  for(i in process_vars) assert_choice(i,names(emi_list),null.ok = FALSE, .var.name = "process_vars")
  # segment_vars
  assert_vector(segment_vars,any.missing = FALSE,min.len = 1,null.ok = TRUE)
  assert_character(segment_vars,any.missing = FALSE,min.len = 1,null.ok = TRUE)
  for(i in segment_vars) assert_choice(i,names(emi_list),null.ok = FALSE, .var.name = "segment_vars")
  
  # check units 
  myunits <- sapply(seq_along(emi_list[[emi_vars]]),function(i){
    units::deparse_unit(emi_list[[emi_vars]][[i]])
  })
  
  if(length(unique(myunits)) == 1){
    myunits <- myunits[1]
  }else{
    cli::cli_abort(c("All emission columns must have the same units."
                     , "x" = "Found units {.val {unique(myunits)}}.")
                   , class = "gtfs2emis_error")
  }
  
  # expand process values
  if(!is.null(pol_vars)){
    rep_pol <- lapply(pol_vars,function(i){ # i = pol_vars
      tmp_rep <- rep(emi_list[[i]],each = length(emi_list[[veh_vars[1]]]))
      #tmp_rep <- rep(emi_list[[i]],each = length(emi_list[[process_vars[1]]]))
      tmp_rep <- rep(tmp_rep,length(emi_list[[process_vars[1]]]))
    })
  }
  if(!is.null(veh_vars)){
    rep_veh <- lapply(veh_vars,function(i){ # i = veh_type
      rep(emi_list[[i]],length(emi_list[[process_vars[1]]]) * length(emi_list[[pol_vars[1]]]))
    })
  }
  if(!is.null(process_vars)){
    rep_pro <- lapply(process_vars,function(i){ # i = veh_type
      rep(emi_list[[i]],each = length(emi_list[[veh_vars[1]]]) * length(emi_list[[pol_vars[1]]]))
    })
  }
  for(i in emi_vars){ # i = "EF"
    if("units" %in% class(emi_list[[i]])){
      emi_list[[i]] <- data.table::as.data.table(emi_list[[i]])
    }
  }
  # merge------
  # stack the K emission columns (N rows each) into one column, in one pass;
  # label k is repeated over the N rows of column k
  emi_cols <- emi_list[[emi_vars]]
  n_col <- length(emi_cols)
  n_row <- length(emi_cols[[1]])
  if(any(lengths(emi_cols) != n_row)){
    cli::cli_abort("All emission columns of {.arg emi_list${emi_vars}} must have the same length."
                   , class = "gtfs2emis_error")
  }
  emi_values <- unlist(emi_cols, use.names = FALSE)
  emi_attr <- attributes(emi_cols[[1]])   # keep the units of the emission columns
  emi_attr$names <- NULL
  attributes(emi_values) <- emi_attr
  tmp_dt <- data.table::data.table(emi_values)
  names(tmp_dt) <- emi_vars
  add_labels <- function(vars, labels){
    for(j in seq_along(labels)){
      data.table::set(tmp_dt, j = vars[j]
                      , value = rep(labels[[j]][seq_len(n_col)], each = n_row))
    }
  }
  # variables (pol, veh)
  if(!is.null(veh_vars))     add_labels(veh_vars, rep_veh)
  if(!is.null(pol_vars))     add_labels(pol_vars, rep_pol)
  if(!is.null(process_vars)) add_labels(process_vars, rep_pro)
  # variables (segment)
  for(j in seq_along(segment_vars)){
    seg_values <- emi_list[[segment_vars[j]]]
    if(!length(seg_values) %in% c(1, n_row)){
      cli::cli_abort(c("{.arg emi_list${segment_vars[j]}} must have length 1 or {n_row} (the number of segments)."
                       , "x" = "It has length {length(seg_values)}.")
                     , class = "gtfs2emis_error")
    }
    if(length(seg_values) != 1) seg_values <- rep(seg_values, n_col)
    data.table::set(tmp_dt, j = segment_vars[j], value = seg_values)
  }
  # rename
  all_vars = c(veh_vars, pol_vars,emi_vars,process_vars)
  data.table::setcolorder(tmp_dt,neworder = all_vars[!is.null(all_vars)])
  # export
  return(tmp_dt)
}